		if u.SessionsTotal != 2 {
			t.Errorf("update %d: SessionsTotal = %d, want 2", i, u.SessionsTotal)
		}
		if u.SessionsDone != i+1 {
			t.Errorf("update %d: SessionsDone = %d, want %d", i, u.SessionsDone, i+1)
		}
