	daemonProgress := progress.withPhase(tui.PhaseDaemon)
	workspaceStarted := time.Now()
	report.Workspace, err = registerRepoInWorkspace(ctx, cmd, perRepo, setupOpts.workspace, repoDir, storage.Key)
