			}
		}
	}

	facts := report.Facts
	factsValue := fmt.Sprintf("%s %s %s",
		render.Bar(facts.Distilled, facts.Sessions, summaryBarWidth),
		render.Ratio(facts.Distilled, facts.Sessions),
		render.Dim("sessions distilled"))
	row("facts", factsValue, "")

	row("backfill", setupPhaseValue(render, report.Backfill, tui.PhaseBackfill, "running in the background"), phaseTiming(timings, "backfill"))
	row("workspace", render.Mark(tui.MarkDone)+" "+render.PhasePaint(tui.PhaseDaemon, report.Workspace.Name), phaseTiming(timings, "workspace"))
	row("daemon", setupDaemonValue(render, report.Daemon, brainCmd), phaseTiming(timings, "daemon"))
	// Say plainly, at the moment of install, that this is a persistent service
	// and where its unit lives. "installed (io.entire.brain-watch.1a2b3c4d)"
	// does not tell a first-time reader that something now survives reboots.
	if report.Daemon.Installed && report.Daemon.UnitPath != "" {
		fmt.Fprintf(out, "  %-*s %s\n", setupSummaryLabelWidth, "",
			render.Dim("persistent service, starts again at every login: "+report.Daemon.UnitPath))
	}
	// What the ONE machine-wide watcher covers. Render-only: `setup --json` is a
	// published contract and a new field in it is a breaking change, so this is
	// derived here from the plan rather than added to setupReport.
	if report.Daemon.Installed {
		if coverage := describeWatchPlanCoverage(watchPlan); coverage != "" {
			fmt.Fprintf(out, "  %-*s %s\n", setupSummaryLabelWidth, "", render.Dim(coverage))
		}
	}

	for _, warning := range report.Warnings {
		fmt.Fprintf(out, "  %-*s %s %s\n", setupSummaryLabelWidth, "", render.Mark(tui.MarkFailed), render.PhasePaint(tui.PhaseSkipped, warning))
	}

	fmt.Fprintf(out, "\n%s\n", render.Bold("Next"))
	next := [][2]string{
		{brainCmd + " overview", "what this project is"},
		{brainCmd + ` brief "<task>"`, "task-shaped context"},
		{brainCmd + " status", "backfill progress and daemon health"},
	}
	// Name the removal command wherever the thing it removes was installed.
	// setup installs a persistent, restart-forever service by default, and
	// --uninstall-daemon appeared ONLY in `setup --help`: nothing in setup's
	// own output, this block, or `status` told a first-time user that a service
	// now exists on their machine or how to take it off. Surfacing it does not
	// change the default -- whether the default should be on is a product call,
		report.Instant.Detail = reasons
		if instantErr != nil {
			return fmt.Errorf("instant phase failed, the brain is not usable: %w", instantErr)
		}
		return fmt.Errorf("instant phase failed, every component failed: %s", reasons)
	}
	report.Instant.State = "ok"
	if len(failed) > 0 {
		report.Instant.State = "degraded"
		report.Instant.Detail = setupInstantFailureReasons(nil, failed)
	}
	summary := setupComponentSummary(built, failed)
	if summary != "" {
		summary += "; "
	}
	instantTask.Update(fmt.Sprintf("instant core ready in %s %s %sthe brain is queryable now",
		roundedSeconds(seconds), progress.dash(), summary))
	instantTask.Finish(nil)
	reportSetupComponentFailures(progress, failed, brainCmd)

	report.Facts = factsBackfillStatusForBrain(storage.BrainDir)

	// Phase 2 — BACKFILL (detached, spends tokens).
	backfillStarted := time.Now()
	report.Backfill = runSetupBackfill(ctx, progress.withPhase(tui.PhaseBackfill), perRepo, setupOpts, steps, storage, repoDir, &report, brainCmd)
	timings.record("backfill", time.Since(backfillStarted))

	// Phase 3 — DAEMON (workspace registration + one machine-wide watcher).
	daemonProgress := progress.withPhase(tui.PhaseDaemon)
	workspaceStarted := time.Now()
	report.Workspace, err = registerRepoInWorkspace(ctx, cmd, perRepo, setupOpts.workspace, repoDir, storage.Key)
	if err != nil {
		report.Warnings = append(report.Warnings, "workspace registration failed: "+err.Error())
		daemonProgress.Skip("workspace registration: " + err.Error())
	} else if report.Workspace.Already {
		daemonProgress.Skip(fmt.Sprintf("workspace %q already has this repo", report.Workspace.Name))
	} else {
		task := daemonProgress.BeginPhase("workspace registration", tui.PhaseDaemon)
		task.Update(fmt.Sprintf("workspace %q now tracks %s", report.Workspace.Name, report.Workspace.RepoKey))
		task.Finish(nil)
	}
	timings.record("workspace", time.Since(workspaceStarted))

	// Record this workspace's tuning in the machine-level plan BEFORE the daemon
	// is installed, so the watcher's very first tick reads a plan that already
	// contains this repo's workspace instead of reporting "nothing to watch".
	// A failure here is a warning, not a fatal: everything the deterministic
	// phases built stays usable, and the next `setup` re-attempts it.
	var watchPlanErr error
	if !setupOpts.noDaemon {
		if _, watchPlanErr = recordSetupWatchPlan(perRepo.Env, setupOpts.daemonName, setupWatchPlanEntryFor(setupOpts, steps.now())); watchPlanErr != nil {
	cc_fix='install your distribution C toolchain, e.g. apt install build-essential'
