			}
			if ctx.Err() != nil {
				fmt.Fprintln(out, "[watch] stopping")
				return nil
			}
		}
		if w.once {
			return nil
		}
		select {
		case <-ctx.Done():
			fmt.Fprintln(out, "[watch] stopping")
			return nil
		case <-time.After(watchPlanSleep(plan, w.interval)):
